code.Exchange.purchaseInternal(uint256,addres:
function purchaseInternal(uint256 _incomingEthereum, address _referredBy)
 notContract()
 internal
 returns(uint256) {
 uint256 purchaseEthereum = _incomingEthereum;
 uint256 excess;
 if(purchaseEthereum > 2 ether) {
 if (SafeMath.sub(address(this).balance, purchaseEthereum) <= 80 ether) {
 purchaseEthereum = 2 ether;
 excess = SafeMath.sub(_incomingEthereum, purchaseEthereum);
 }
 }
 purchaseTokens(purchaseEthereum, _referredBy, false);
 if (excess > 0) {
 msg.sender.transfer(excess);
 }
 }

